// Bounded deterministic models: seconds/units, not measurements of a real service.
export function simulateVideo({pattern='bursty',startup=2}={}){
 if(!['steady','bursty','slow'].includes(pattern)||![0,2,4].includes(Number(startup)))throw Error('เลือกค่าจาก Lab');
 const arrivals=pattern==='steady'?Array(12).fill(1):pattern==='slow'?Array.from({length:12},(_,i)=>i%2?0:1):[3,0,0,3,0,0,3,0,0,3,0,0];
 let buffer=0,started=false,stalls=0,played=0;const steps=[];
 arrivals.forEach((incoming,tick)=>{buffer+=incoming;if(!started&&buffer>=Number(startup)&&buffer>0)started=true;let event='รอ startup';if(started){if(buffer>=1){buffer--;played++;event='เล่น 1 วินาที';}else{stalls++;event='สะดุด / stall';}}steps.push({tick,incoming,buffer,event,played,stalls});});return {steps,arrivals,played,stalls,pattern,startup:Number(startup)};
}
export function simulateRate({policy='shape',rate=2,bucket=4}={}){
 if(!['shape','police'].includes(policy)||![1,2,4].includes(Number(rate))||![2,4,8].includes(Number(bucket)))throw Error('เลือกค่าจาก Lab');
 let tokens=Number(bucket),id=0;const queue=[],steps=[];let dropped=0,sent=0;
 for(let tick=0;tick<12;tick++){if(tick)tokens=Math.min(Number(bucket),tokens+Number(rate));const incoming=tick<4?Array.from({length:5},()=>++id):[];let outgoing=[],lost=[];
  if(policy==='shape'){queue.push(...incoming);while(tokens>=1&&queue.length){tokens--;outgoing.push(queue.shift());}}
  else for(const packet of incoming){if(tokens>=1){tokens--;outgoing.push(packet);}else lost.push(packet);}
  sent+=outgoing.length;dropped+=lost.length;steps.push({tick,incoming,outgoing,lost,queue:[...queue],tokens,sent,dropped});}
 return {steps,policy,rate:Number(rate),bucket:Number(bucket),sent,dropped,pending:queue.length};
}
const common={track:'network',section:'transport',conceptLab:true,visual:'network',scene:'network',time:20,tag:'NETWORK / SERVICE LAB',states:[],steps:['อ่านหน่วยและสมมติฐาน','เทียบสองการตั้งค่าจนจบ','ตอบจากผลคำนวณ'],scenario:'แบบจำลองบริการ',work:'เปลี่ยนทีละค่า เล่นจนจบ และเทียบผลก่อน/หลัง'};
export const serviceLessons=[
 {...common,id:'video-buffer',title:'Video Buffer: ทำไมวิดีโอสะดุด',subtitle:'ข้อมูลมาถึงไม่สม่ำเสมอ กับเวลาเริ่มเล่น',explain:'Buffer เก็บข้อมูลก่อนใช้ การรอก่อนเริ่มเล่นช่วยรับมือความผันผวนแต่เพิ่ม startup delay ถ้าอัตรารับเฉลี่ยต่ำกว่าอัตราเล่น Buffer ไม่ได้ทำให้รับเร็วขึ้น Lab ใช้หน่วยวินาทีสื่อ ไม่ใช่ codec/bitrate หรือ video player จริง',source:'https://www.rfc-editor.org/rfc/rfc3393',question:'Buffer เพิ่มความจุลิงก์หรือไม่?',choices:['ไม่เพิ่ม แลกเวลารอกับความต่อเนื่อง','เพิ่มเสมอ','ทำให้ไม่สะดุดทุกกรณี'],answer:0},
 {...common,id:'rate-control',title:'Shaping / Policing: หน่วงหรือทิ้ง',subtitle:'Token bucket ที่คำนวณจริงจาก burst',explain:'Token bucket มีอัตราเติมและความจุสำหรับ burst Shaping เก็บงานรอเมื่อไม่มี token ส่วน Policing ใน Lab นี้ทิ้งงานเกินโควตาทันที ระบบจริงอาจ remark และมีหลาย bucket; DSCP marking ต้องมี classification/queue policy รองรับ ไม่เพิ่ม bandwidth เอง',source:'https://www.rfc-editor.org/rfc/rfc2475',question:'เมื่อ token ไม่พอ Shaping ใน Lab ทำอะไร?',choices:['รอในคิว ไม่ใช่เพิ่มความจุลิงก์','ทิ้งทันทีทุกงาน','ส่งเกิน rate ได้ไม่จำกัด'],answer:0},
].map(l=>({...l,hint:l.explain,reason:l.explain}));
export function serviceScene(l,m){const video=l.id==='video-buffer';const nodes=[{id:'in',name:video?'สื่อที่ดาวน์โหลด':'Burst source',address:'หน่วยสมมติ',kind:'client',position:[-5,0]},{id:'buffer',name:video?'Playback buffer':'Token bucket / queue',address:'บริบทเชิงตรรกะ ไม่ใช่อุปกรณ์เพิ่ม',kind:'router',position:[0,0]},{id:'out',name:video?'Playback':'Conforming output',address:'ผลจากแบบจำลอง',kind:'server',position:[5,0]},{id:'drop',name:'Excess / stall',address:'ไม่ใช่ Server จริง',kind:'server',position:[0,4]}];const links=[['in','buffer'],['buffer','out'],['buffer','drop']].map(([from,to])=>({id:from+'-'+to,from,to}));return {nodes,links,steps:m.steps.map(s=>({title:`เวลา ${s.tick} s`,detail:video?s.event:'Token budget จำกัด output',fields:video?[['Buffer',s.buffer+' วินาที'],['Playback',s.event],['Stalls',s.stalls]]:[['Tokens',s.tokens],['Queued',s.queue.length],['Drop',s.lost.length]],active:['buffer'],edges:[],status:video?s.event.includes('stall')?'blocked':'ok':s.lost.length?'blocked':'ok',nodeUpdates:{buffer:video?`${s.buffer} วินาทีรอเล่น`:`tokens ${s.tokens} / queued ${s.queue.length}`},transfers:video?[...(s.incoming?[{from:'in',to:'buffer',message:`รับ ${s.incoming} วินาทีสื่อ`}]:[]),...(s.event==='เล่น 1 วินาที'?[{from:'buffer',to:'out',message:'consume 1 วินาที'}]:[])]:[...s.outgoing.map(id=>({from:'buffer',to:'out',message:`conform #${id}`})),...s.lost.map(id=>({from:'buffer',to:'drop',message:`excess #${id}`}))]}))};}
export function serviceSurface(l){const video=l.id==='video-buffer';return `<section class="service-lab quality-lab"><h2>${l.title}</h2><p>คำนวณใน browser ไม่ติดต่อบริการจริง · tick 1 วินาที · ${video?'สื่อถึงก่อน consume ในแต่ละ tick; ละ codec/adaptive bitrate/rebuffer threshold':'แต่ละงานใช้ 1 token; shape ใช้คิวไม่จำกัดในช่วงสั้น; police ทิ้ง excess ไม่ remark'}</p><form>${video?'<label>ข้อมูลที่มาถึง<select name="pattern"><option value="bursty">3,0,0 ซ้ำ · เฉลี่ย 1/s</option><option value="steady">1/s สม่ำเสมอ</option><option value="slow">1,0 ซ้ำ · เฉลี่ย 0.5/s</option></select></label><label>Startup buffer<select name="startup"><option>2</option><option>0</option><option>4</option></select></label>':'<label>Policy<select name="policy"><option value="shape">Shaping</option><option value="police">Policing (drop)</option></select></label><label>Rate token/s<select name="rate"><option>2</option><option>1</option><option>4</option></select></label><label>Bucket tokens<select name="bucket"><option>4</option><option>2</option><option>8</option></select></label>'}<button class="button">คำนวณใหม่</button></form><div class="mechanism-stage is-3d" style="height:380px" data-service-scene></div><p>3D INTERACTIVE · Buffer/Token bucket คือพื้นที่เชิงตรรกะ</p><div class="mechanism-controls"><button data-service-play>▶ เล่น</button><button data-service-reset>เริ่มดูใหม่</button><button data-service-view>รีเซ็ตมุมมอง</button><label>ขั้นตอน<input data-service-step type="range" min="0" max="11" value="0"></label></div><pre data-service-result aria-live="polite"></pre><p>ภารกิจ: อ่านสอง configuration จนจบแล้วตอบ</p><p data-service-seen></p><h3>${l.question}</h3><div class="choices">${l.choices.map((v,i)=>`<button data-service-answer="${i}">${v}</button>`).join('')}</div><button data-service-hint>ขอคำใบ้</button><p data-service-feedback role="status"></p></section>`;}
export function initService(l,complete){const root=document.querySelector('.service-lab'),form=root.querySelector('form'),range=root.querySelector('[data-service-step]'),button=root.querySelector('[data-service-play]'),seen=new Set();let scene,index=0,timer,disposed=false,model;
 const stop=()=>{clearInterval(timer);timer=null;button.textContent='▶ เล่น';};
 const draw=()=>{range.value=index;const s=model.steps[index];root.querySelector('[data-service-result]').textContent=l.id==='video-buffer'?`รับ ${s.incoming}s · buffer ${s.buffer}s · ${s.event}\nเล่นสะสม ${s.played}s · stalls ${s.stalls}`:`tokens ${s.tokens} · ส่ง ${s.outgoing.join(', ')||'ไม่มี'}\nรอ ${s.queue.join(', ')||'ไม่มี'} · Drop ${s.lost.join(', ')||'ไม่มี'}`;scene?.showStep(index);if(index===11)seen.add(JSON.stringify(Object.fromEntries(new FormData(form))));root.querySelector('[data-service-seen]').textContent=`อ่านจนจบ ${seen.size} การตั้งค่า`;};
 const rebuild=()=>{stop();const p=Object.fromEntries(new FormData(form));model=l.id==='video-buffer'?simulateVideo(p):simulateRate(p);index=0;scene?.setModel(serviceScene(l,model));draw();};rebuild();import('./network-mechanism-scene.js').then(({mountScene})=>{if(disposed)return;scene=mountScene(root.querySelector('[data-service-scene]'),{lesson:l,initialModel:serviceScene(l,model)});scene.showStep(index);}).catch(()=>{root.querySelector('[data-service-scene]').textContent='3D ไม่พร้อม ใช้ผลคำนวณด้านล่างได้';});
 form.onsubmit=e=>{e.preventDefault();rebuild();};range.oninput=()=>{stop();index=Number(range.value);draw();};button.onclick=()=>{if(timer){stop();return;}if(index===11)index=0;button.textContent='Ⅱ หยุด';draw();timer=setInterval(()=>{if(!root.isConnected){stop();return;}index++;draw();if(index===11)stop();},700);};root.querySelector('[data-service-reset]').onclick=()=>{stop();index=0;draw();};root.querySelector('[data-service-view]').onclick=()=>scene?.resetView();root.querySelector('[data-service-hint]').onclick=()=>root.querySelector('[data-service-feedback]').textContent=l.explain;root.querySelectorAll('[data-service-answer]').forEach(b=>b.onclick=()=>{const f=root.querySelector('[data-service-feedback]');if(seen.size<2){f.textContent='อ่านสองการตั้งค่าจนจบก่อนตอบ';return;}if(Number(b.dataset.serviceAnswer)!==l.answer){f.textContent='ยังไม่ตรงกับกลไก ลองใช้คำใบ้และเปรียบเทียบอีกครั้ง';return;}f.textContent='✓ ผ่าน — '+l.explain;complete();});return {dispose(){disposed=true;stop();scene?.dispose();}};}
